import{_ as t,o,c as a,ae as s}from"./chunks/framework.B2FZg54p.js";const r="/heidrun/experiments/web-doc-by-ai/documentation_images/pane_focus_history/controls_annotated.svg",n="/heidrun/experiments/web-doc-by-ai/documentation_images/pane_focus_history/history_list_annotated.svg",f=JSON.parse('{"title":"Go back and forward through the panes that had the focus","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/pane_focus_history.md","filePath":"documentation/pane_focus_history.md"}'),i={name:"documentation/pane_focus_history.md"};function h(l,e,d,c,u,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<div class="pane-focus-history-page"><h1 id="go-back-and-forward-through-the-panes-that-had-the-focus" tabindex="-1">Go back and forward through the panes that had the focus <a class="header-anchor" href="#go-back-and-forward-through-the-panes-that-had-the-focus" aria-label="Permalink to &quot;Go back and forward through the panes that had the focus&quot;">​</a></h1><p>Return to a pane that had the keyboard focus earlier, and move forward again, with the buttons or the keyboard shortcuts.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>A pane is one terminal inside a tab. The pane that has the keyboard focus is the pane that receives what you type.</p><p>Heidrun keeps one pane focus history for the whole window. The history covers all workspaces and all tabs, and it is empty when Heidrun starts.</p><h2 id="where-the-buttons-are" tabindex="-1">Where the buttons are <a class="header-anchor" href="#where-the-buttons-are" aria-label="Permalink to &quot;Where the buttons are&quot;">​</a></h2><p>The <strong>Back</strong> button (left arrow) and the <strong>Forward</strong> button (right arrow) are in the top bar, at the very top of the window, just left of the search button.</p><p><img src="'+r+'" alt="The top bar of Heidrun with the Back button and the Forward button, left of the search button"></p><h2 id="go-back-or-forward-one-pane" tabindex="-1">Go back or forward one pane <a class="header-anchor" href="#go-back-or-forward-one-pane" aria-label="Permalink to &quot;Go back or forward one pane&quot;">​</a></h2><ol><li>Click <strong>Back</strong> to focus the previous pane, or click <strong>Forward</strong> to focus the next pane.</li><li>Heidrun selects the workspace and the tab of that pane.</li><li>Check that the destination pane has the keyboard focus.</li></ol><h2 id="choose-a-pane-from-a-list" tabindex="-1">Choose a pane from a list <a class="header-anchor" href="#choose-a-pane-from-a-list" aria-label="Permalink to &quot;Choose a pane from a list&quot;">​</a></h2><ol><li>Hold the <strong>Back</strong> button or the <strong>Forward</strong> button for about half a second, until a list opens below the button.</li><li>Release the button. The list stays open, and the release does not move you.</li><li>Read the list. The <strong>Back</strong> list shows earlier panes, and the <strong>Forward</strong> list shows later panes. The nearest pane is first.</li><li>Click a row to focus that pane and close the list.</li></ol><p>Each row starts with the workspace, then the tab. The agent type and the custom name of the pane may follow when they are different from the earlier parts. Names that repeat are left out, so two rows can look the same.</p><p><img src="'+n+'" alt="The list of earlier panes that opens below the Back button"></p><h2 id="close-the-list" tabindex="-1">Close the list <a class="header-anchor" href="#close-the-list" aria-label="Permalink to &quot;Close the list&quot;">​</a></h2><ul><li>Press <strong>Escape</strong>. The list closes without selecting an entry, and the keyboard focus returns to the button that opened it.</li><li>Click outside both the list and the button that opened it. The list closes, but the click still acts on the element that you clicked and may focus the clicked pane.</li></ul><h2 id="use-the-keyboard-shortcuts" tabindex="-1">Use the keyboard shortcuts <a class="header-anchor" href="#use-the-keyboard-shortcuts" aria-label="Permalink to &quot;Use the keyboard shortcuts&quot;">​</a></h2><p>Press <kbd>⌘[</kbd> to go back and <kbd>⌘]</kbd> to go forward. Heidrun matches the characters &quot;[&quot; and &quot;]&quot;, so the shortcuts work on a French keyboard. The full list of shortcuts is on the <a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a> page.</p><p>A pinned pane gets the focus where it is, and the tab that you are on does not change.</p><h2 id="use-the-shortcuts-when-the-file-explorer-is-open" tabindex="-1">Use the shortcuts when the file explorer is open <a class="header-anchor" href="#use-the-shortcuts-when-the-file-explorer-is-open" aria-label="Permalink to &quot;Use the shortcuts when the file explorer is open&quot;">​</a></h2><p>The file explorer is the window that opens with ⌘P. It shows a file tree and an editor, and its title is <strong>Files</strong>. It is not the large Git window that opens from the Files sidebar section. While the file explorer is open, <kbd>⌘[</kbd> and <kbd>⌘]</kbd> do nothing, because the file explorer keeps them for its editor.</p><ol><li>Close the file explorer with the <strong>X</strong> button; its tooltip is “Close the file browser (Escape)”. This is the reliable way to close it.</li><li>If some files have unsaved changes, choose one of the three answers that Heidrun offers.</li><li>Confirm that the file explorer has closed before trying <kbd>⌘[</kbd> or <kbd>⌘]</kbd> again, and check that the matching direction is available.</li></ol><p>You can use <strong>Escape</strong> only when the editor does not have the keyboard focus and no menu, naming mode, selected row, diff, or search text is using the key. Otherwise, use <strong>X</strong>.</p><table tabindex="0"><thead><tr><th>Choice</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Save all and close</strong></td><td>Heidrun saves every file, then closes the file explorer. If a save fails, the file explorer stays open on the file with the error.</td></tr><tr><td><strong>Discard the changes</strong></td><td>Heidrun closes the file explorer and the unsaved changes are lost.</td></tr><tr><td><strong>Cancel</strong></td><td>The file explorer stays open and the navigation stops.</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="Back button is disabled"><h3 id="back-button-is-disabled" tabindex="-1">Back button is disabled <a class="header-anchor" href="#back-button-is-disabled" aria-label="Permalink to &quot;Back button is disabled&quot;">​</a></h3><p><strong>Cause</strong>: No earlier entry exists before the current entry in the pane focus history.</p><p><strong>Solution</strong>:</p><ol><li>Focus one pane and keep keyboard focus on that pane for at least half a second.</li><li>Focus a different pane, keep both panes open, and keep keyboard focus on the different pane for at least half a second.</li></ol><p><strong>Check</strong>: The <strong>Back</strong> button is enabled.</p></section><section class="documentation-troubleshooting-topic" aria-label="Forward button is disabled"><h3 id="forward-button-is-disabled" tabindex="-1">Forward button is disabled <a class="header-anchor" href="#forward-button-is-disabled" aria-label="Permalink to &quot;Forward button is disabled&quot;">​</a></h3><p><strong>Cause</strong>: No later entry exists after the current entry in the pane focus history.</p><p><strong>Solution</strong>:</p><ol><li>First follow the steps for <a href="#back-button-is-disabled">a disabled Back button</a> so that an earlier entry exists.</li><li>Click <strong>Back</strong> once.</li><li>Do not focus a new pane after moving <strong>Back</strong>.</li></ol><p><strong>Check</strong>: The <strong>Forward</strong> button is enabled.</p></section><section class="documentation-troubleshooting-topic" aria-label="The history is missing or empty"><h3 id="the-history-is-missing-or-empty" tabindex="-1">The history is missing or empty <a class="header-anchor" href="#the-history-is-missing-or-empty" aria-label="Permalink to &quot;The history is missing or empty&quot;">​</a></h3><p><strong>Cause</strong>: Normal focus changes are recorded after a pane keeps the focus for about half a second, and the history is empty when Heidrun starts; before moving, <strong>Back</strong>, <strong>Forward</strong>, and choosing a history entry record the currently focused pane immediately, even if it has not yet been recorded.</p><p><strong>Solution</strong>:</p><ol><li>Focus one pane and keep keyboard focus on that pane for at least half a second.</li><li>Focus a different pane, keep both panes open, and keep keyboard focus on the different pane for at least half a second.</li><li>Hold the enabled <strong>Back</strong> button to open the earlier list.</li></ol><p><strong>Check</strong>: The list shows the first pane.</p></section><section class="documentation-troubleshooting-topic" aria-label="The shortcut ⌘[ or ⌘] does nothing"><h3 id="the-shortcut-⌘-or-⌘-does-nothing" tabindex="-1">The shortcut ⌘[ or ⌘] does nothing <a class="header-anchor" href="#the-shortcut-⌘-or-⌘-does-nothing" aria-label="Permalink to &quot;The shortcut ⌘[ or ⌘] does nothing&quot;">​</a></h3><p><strong>Cause</strong>: The file explorer may use the shortcut, or it may still be open because <strong>Cancel</strong> returned you to editing.</p><p><strong>Solution</strong>:</p><ol><li>Close the file explorer with <strong>X</strong>. Use <strong>Escape</strong> only when the editor does not have the keyboard focus and no menu, naming mode, selected row, diff, or search text is using the key.</li><li>If Heidrun asks about unsaved changes, choose <strong>Save all and close</strong> to save and close, or <strong>Discard the changes</strong> to close and lose those changes.</li><li>If saving fails, leave the file explorer open on the file with the error; do not expect the shortcut to work yet.</li><li>If you choose <strong>Cancel</strong>, return to editing and stop here; the file explorer remains open, so do not try the shortcut again.</li><li>After choosing a closing option, confirm that the file explorer has closed and that the matching <strong>Back</strong> or <strong>Forward</strong> direction is available before retrying the shortcut.</li></ol><p><strong>Check</strong>: The file explorer is closed and the matching direction is available before you retry; after retrying, the focus moves to the pane in that direction.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to see every shortcut of Heidrun</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/browse_project_files.html">Browse project files</a>: to learn more about the Files sidebar section</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/files_sidebar_section_controls.html">Files sidebar section controls</a>: to look up the controls of the Files sidebar section</li></ul></div>',1)])])}const g=t(i,[["render",h]]);export{f as __pageData,g as default};
